  // Technique detail info
  'techniques.box.detail': '\u0418\u0437\u043F\u043E\u043B\u0437\u0432\u0430 \u0441\u0435 \u043E\u0442 Navy SEALs \u0437\u0430 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0430 \u0441\u0442\u0440\u0435\u0441\u0430. \u0420\u0430\u0432\u043D\u0438 \u0444\u0430\u0437\u0438 \u043D\u0430 \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0435, \u0437\u0430\u0434\u044A\u0440\u0436\u0430\u043D\u0435, \u0438\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0435 \u0438 \u0437\u0430\u0434\u044A\u0440\u0436\u0430\u043D\u0435 \u0441\u044A\u0437\u0434\u0430\u0432\u0430\u0442 \u0443\u0441\u043F\u043E\u043A\u043E\u044F\u0432\u0430\u0449 \u0440\u0438\u0442\u044A\u043C, \u043A\u043E\u0439\u0442\u043E \u043D\u0430\u043C\u0430\u043B\u044F\u0432\u0430 \u043A\u043E\u0440\u0442\u0438\u0437\u043E\u043B\u0430 \u0438 \u043F\u043E\u0434\u043E\u0431\u0440\u044F\u0432\u0430 \u0444\u043E\u043A\u0443\u0441\u0430.',
  'techniques.fourSevenEight.detail': '\u0420\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u0435\u043D \u043E\u0442 \u0434-\u0440 \u0410\u043D\u0434\u0440\u044E \u0423\u0430\u0439\u043B. \u0423\u0434\u044A\u043B\u0436\u0435\u043D\u043E\u0442\u043E \u0438\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0435 \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u0430 \u043F\u0430\u0440\u0430\u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u043D\u0430\u0442\u0430 \u043D\u0435\u0440\u0432\u043D\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430, \u0438\u0434\u0435\u0430\u043B\u043D\u043E \u0437\u0430 \u0437\u0430\u0441\u043F\u0438\u0432\u0430\u043D\u0435 \u0437\u0430 \u043C\u0438\u043D\u0443\u0442\u0438.',
  'techniques.physioSigh.detail': '\u041E\u0442\u043A\u0440\u0438\u0442\u043E \u043E\u0442 \u043D\u0435\u0432\u0440\u043E\u043B\u043E\u0433\u0430 \u043E\u0442 \u0421\u0442\u0430\u043D\u0444\u043E\u0440\u0434 \u0434-\u0440 \u0410\u043D\u0434\u0440\u044E \u0425\u0443\u0431\u0435\u0440\u043C\u0430\u043D. \u0414\u0432\u043E\u0439\u043D\u043E \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0435 \u0441 \u0434\u044A\u043B\u044A\u0433 \u0438\u0437\u0434\u0438\u0448 \u0435 \u043D\u0430\u0439-\u0431\u044A\u0440\u0437\u0438\u044F\u0442 \u043D\u0430\u0447\u0438\u043D \u0437\u0430 \u043D\u0430\u043C\u0430\u043B\u044F\u0432\u0430\u043D\u0435 \u043D\u0430 \u0441\u0442\u0440\u0435\u0441\u0430 \u0432 \u0440\u0435\u0430\u043B\u043D\u043E \u0432\u0440\u0435\u043C\u0435.',
  'techniques.coherence.detail': '\u0414\u0438\u0448\u0430\u043D\u0435 \u0441 5,5 \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0438\u044F \u0432 \u043C\u0438\u043D\u0443\u0442\u0430 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0430 \u0441\u044A\u0440\u0434\u0435\u0447\u043D\u0438\u044F \u0440\u0438\u0442\u044A\u043C, \u043A\u0440\u044A\u0432\u043D\u043E\u0442\u043E \u043D\u0430\u043B\u044F\u0433\u0430\u043D\u0435 \u0438 \u043D\u0435\u0440\u0432\u043D\u0430\u0442\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u2014 \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u0439\u043A\u0438 \u0441\u044A\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043D\u0430\u0440\u0435\u0447\u0435\u043D\u043E \u201E\u043A\u043E\u0433\u0435\u0440\u0435\u043D\u0442\u043D\u043E\u0441\u0442\u201C \u0437\u0430 \u043E\u043F\u0442\u0438\u043C\u0430\u043B\u043D\u0430 \u0412\u0421\u0420.',
  'techniques.triangle.detail': '\u041C\u0435\u043A 3-\u0444\u0430\u0437\u0435\u043D \u043C\u043E\u0434\u0435\u043B, \u0438\u0434\u0435\u0430\u043B\u0435\u043D \u0437\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0449\u0438. \u0411\u0430\u043B\u0430\u043D\u0441\u0438\u0440\u0430 \u043D\u0435\u0440\u0432\u043D\u0430\u0442\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0431\u0435\u0437 \u0437\u0430\u0434\u044A\u0440\u0436\u0430\u043D\u0435 \u043D\u0430 \u0434\u0438\u0448\u0430\u043D\u0435\u0442\u043E, \u043A\u043E\u0435\u0442\u043E \u0433\u043E \u043F\u0440\u0430\u0432\u0438 \u043B\u0435\u0441\u043D\u043E \u0438 \u0434\u043E\u0441\u0442\u044A\u043F\u043D\u043E \u0437\u0430 \u0432\u0441\u0435\u043A\u0438.',
  'techniques.power.detail': '\u0412\u0434\u044A\u0445\u043D\u043E\u0432\u0435\u043D\u043E \u043E\u0442 \u043C\u0435\u0442\u043E\u0434\u0430 \u043D\u0430 \u0412\u0438\u043C \u0425\u043E\u0444. \u0411\u044A\u0440\u0437\u043E \u0434\u0438\u0448\u0430\u043D\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u0432\u0430\u043D\u043E \u043E\u0442 \u0437\u0430\u0434\u044A\u0440\u0436\u0430\u043D\u0435 \u043F\u043E\u0432\u0438\u0448\u0430\u0432\u0430 \u0435\u043D\u0435\u0440\u0433\u0438\u044F\u0442\u0430, \u043E\u0449\u0435\u043B\u0430\u0447\u0430\u0432\u0430 \u043A\u0440\u044A\u0432\u0442\u0430 \u0438 \u0443\u0441\u0438\u043B\u0432\u0430 \u0438\u043C\u0443\u043D\u043D\u0438\u044F \u043E\u0442\u0433\u043E\u0432\u043E\u0440.',
  'techniques.fourFourSixTwo.detail': '\u0423\u0434\u044A\u043B\u0436\u0435\u043D\u043E\u0442\u043E \u0438\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0435 (6 \u0441) \u0441\u043F\u0440\u044F\u043C\u043E \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0435\u0442\u043E (4 \u0441) \u043F\u0440\u0435\u0432\u043A\u043B\u044E\u0447\u0432\u0430 \u0442\u044F\u043B\u043E\u0442\u043E \u0432 \u0434\u044A\u043B\u0431\u043E\u043A\u0430 \u0440\u0435\u043B\u0430\u043A\u0441\u0430\u0446\u0438\u044F. \u041A\u0440\u0430\u0442\u043A\u0430\u0442\u0430 \u043F\u0430\u0443\u0437\u0430 \u043C\u0435\u0436\u0434\u0443 \u0446\u0438\u043A\u043B\u0438\u0442\u0435 \u0440\u0435\u0441\u0442\u0430\u0440\u0442\u0438\u0440\u0430 \u0440\u0438\u0442\u044A\u043C\u0430 \u043D\u0430 \u0434\u0438\u0448\u0430\u043D\u0435\u0442\u043E.',
  'techniques.kapalabhati.detail': '\u0414\u0440\u0435\u0432\u043D\u0430 \u0439\u043E\u0433\u0438\u0439\u0441\u043A\u0430 \u0442\u0435\u0445\u043D\u0438\u043A\u0430, \u043E\u0437\u043D\u0430\u0447\u0430\u0432\u0430\u0449\u0430 \u201E\u0441\u0438\u044F\u0435\u043D \u0447\u0435\u0440\u0435\u043F\u201C. \u0411\u044A\u0440\u0437\u0438 \u0435\u043D\u0435\u0440\u0433\u0438\u0447\u043D\u0438 \u0438\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0438\u044F \u043D\u0430\u043F\u044A\u043B\u0432\u0430\u0442 \u0442\u044F\u043B\u043E\u0442\u043E \u0441 \u0435\u043D\u0435\u0440\u0433\u0438\u044F, \u0438\u0437\u0447\u0438\u0441\u0442\u0432\u0430\u0442 \u0443\u043C\u0430 \u0438 \u0443\u043A\u0440\u0435\u043F\u0432\u0430\u0442 \u0434\u0438\u0430\u0444\u0440\u0430\u0433\u043C\u0430\u0442\u0430.',
  'techniques.twoToOne.detail': '\u0418\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0435\u0442\u043E \u0435 \u0434\u0432\u043E\u0439\u043D\u043E \u043F\u043E-\u0434\u044A\u043B\u0433\u043E \u043E\u0442 \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0435\u0442\u043E, \u043C\u0430\u043A\u0441\u0438\u043C\u0438\u0437\u0438\u0440\u0430\u0439\u043A\u0438 \u0438\u0437\u0432\u0435\u0436\u0434\u0430\u043D\u0435\u0442\u043E \u043D\u0430 CO\u2082 \u0438 \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u0430\u0439\u043A\u0438 \u0431\u043B\u0443\u0436\u0434\u0430\u0435\u0449\u0438\u044F \u043D\u0435\u0440\u0432. \u0415\u0434\u0438\u043D \u043E\u0442 \u043D\u0430\u0439-\u0435\u0444\u0435\u043A\u0442\u0438\u0432\u043D\u0438\u0442\u0435 \u043C\u043E\u0434\u0435\u043B\u0438 \u0437\u0430 \u0434\u044A\u043B\u0431\u043E\u043A\u0430 \u0440\u0435\u043B\u0430\u043A\u0441\u0430\u0446\u0438\u044F.',
  'techniques.cyclicSigh.detail': '\u0418\u0437\u0441\u043B\u0435\u0434\u0432\u0430\u043D\u0435 \u043D\u0430 \u0421\u0442\u0430\u043D\u0444\u043E\u0440\u0434 \u043F\u043E\u043A\u0430\u0437\u0430, \u0447\u0435 5 \u043C\u0438\u043D\u0443\u0442\u0438 \u0446\u0438\u043A\u043B\u0438\u0447\u043D\u043E \u0432\u044A\u0437\u0434\u0438\u0448\u0430\u043D\u0435 \u0435 \u043F\u043E-\u0435\u0444\u0435\u043A\u0442\u0438\u0432\u043D\u043E \u0437\u0430 \u043D\u0430\u043C\u0430\u043B\u044F\u0432\u0430\u043D\u0435 \u043D\u0430 \u0441\u0442\u0440\u0435\u0441\u0430 \u043E\u0442 \u043C\u0435\u0434\u0438\u0442\u0430\u0446\u0438\u044F\u0442\u0430. \u0414\u0432\u043E\u0439\u043D\u043E \u0432\u0434\u0438\u0448\u0432\u0430\u043D\u0435 + \u0443\u0434\u044A\u043B\u0436\u0435\u043D\u043E \u0438\u0437\u0434\u0438\u0448\u0432\u0430\u043D\u0435 \u0440\u0435\u0441\u0442\u0430\u0440\u0442\u0438\u0440\u0430 \u043D\u0435\u0440\u0432\u043D\u0430\u0442\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430.',

